        "refs": ["Q0019", "Q0018", "Q0020", "Q0021", "Q0022"],
        "claims": [
          {
            "text": "An abstract class is a class that cannot be instantiated directly; it is defined as abstract and must be subclassed or used via a factory method.",
            "basis": "explicit",
