          },
          {
            "text": "Because an abstract class cannot be instantiated with the new operator, you must obtain an instance through other means such as a factory method.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
