      "definition_text": {
        "text": "In Java, an abstract class is a class declared with the abstract keyword, meaning it cannot be instantiated directly. It serves as a base for other classes and may contain abstract methods that subclasses must implement.",
        "refs": ["Q0019", "Q0018", "Q0020"],
        "claims": [
          {
            "text": "An abstract class is declared with the abstract keyword and cannot be instantiated directly.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
