            "instructional_role": "prerequisite",
            "refs": ["Q0019", "Q0018"],
            "related_refs": []
          },
          {
            "text": "Abstract classes can contain abstract methods that must be implemented by concrete subclasses.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0019"],
            "related_refs": []
          }
        ]
      },
