    },
    {
      "term": {
        "text": "factory method",
        "refs": ["Q0027", "Q0028", "Q0025", "Q0026"],
        "claims": [
          {
            "text": "A factory method is a static method that creates and returns an instance of a class, often used when the class cannot be instantiated directly.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "alternative_valid_approach",
            "refs": ["Q0027", "Q0025"],
            "related_refs": []
          },
          {
            "text": "Factory methods act like factories, creating new objects without using the new operator on abstract classes.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
